#include <string>
#include <algorithm>

using namespace std;

class Solution {
public:
    int minSwaps(string s) {
        int ones = count(s.begin(), s.end(), '1'), n = s.size();
        if (abs(n - 2 * ones) > 1) return -1;

        int swap0 = 0, swap1 = 0;
        for (int i = 0; i < n; ++i) {
            if (s[i] - '0' != i % 2) ++swap0;
            if (s[i] - '0' != (i + 1) % 2) ++swap1;
        }

        if (n % 2 == 0) return min(swap0, swap1) / 2;
        return (ones * 2 > n ? swap1 : swap0) / 2;
    }
};
